require __DIR__.'/bootstrap.php';require_auth();if(!can('customers.view')){http_response_code(403);exit('Forbidden');}header('Content-Type: application/json; charset=utf-8');$rows=$db->query('SELECT c.id customer_id,COALESCE(SUM(CASE WHEN a.status IN("open","partially_applied") THEN a.remaining_amount ELSE 0 END),0) advance_available,COUNT(CASE WHEN a.status IN("open","partially_applied") AND a.remaining_amount>0 THEN 1 END) open_advances FROM customers c LEFT JOIN customer_advances a ON a.customer_id=c.id GROUP BY c.id')->fetchAll();$balances=[];foreach($rows as $row)$balances[(string)$row['customer_id']]=['advance_available'=>(float)$row['advance_available'],'open_advances'=>(int)$row['open_advances']];echo json_encode(['balances'=>$balances],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
